from src.nodes.base import BaseNode
from src.runtime.lookdev import get_lookdev_review
import json

class Hou_Mcp_Lookdev_Review(BaseNode):
    name = "hou_mcp_lookdev_review"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("lookdev_json", "string", widget_type="text", default="")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("review_json",      "string")
        self.add_output("score",            "float")
        self.add_output("grade",            "string")
        self.add_output("production_ready", "bool")

    async def execute(self, inputs):
        lookdev_json = str(inputs.get("lookdev_json", "") or "")
        try:
            lookdev_dict = json.loads(lookdev_json) if lookdev_json.strip() else {}
        except Exception as exc:
            self.log_error(f"Failed to parse lookdev_json: {exc}")
            return {"review_json": "{}", "score": 0.0, "grade": "F", "production_ready": False, "exec_out": True}
        try:
            engine = get_lookdev_review()
            result = engine.review_lookdev(lookdev_dict)
            self.log_info(
                f"Lookdev review: grade={result.grade}, score={result.score:.2f}, "
                f"production_ready={result.production_ready}. "
                f"Findings: {len(result.findings)}."
            )
            return {
                "review_json":      json.dumps(result.to_dict(), sort_keys=True, default=str),
                "score":            result.score,
                "grade":            result.grade,
                "production_ready": result.production_ready,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Lookdev review failed: {exc}")
            return {"review_json": "{}", "score": 0.0, "grade": "F", "production_ready": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Lookdev_Review
